// services/deterministicRandom.ts
var UINT32_RANGE = 4294967296;
var hashDeterministicSeed = (value) => {
  let hash2 = 2166136261;
  for (let index = 0; index < value.length; index += 1) {
    hash2 ^= value.charCodeAt(index);
    hash2 = Math.imul(hash2, 16777619);
  }
  return hash2 >>> 0;
};
var createDeterministicRng = (seed2) => {
  let state = typeof seed2 === "number" ? seed2 >>> 0 : hashDeterministicSeed(seed2);
  return () => {
    state = state + 1831565813 >>> 0;
    let value = state;
    value = Math.imul(value ^ value >>> 15, value | 1);
    value ^= value + Math.imul(value ^ value >>> 7, value | 61);
    return ((value ^ value >>> 14) >>> 0) / UINT32_RANGE;
  };
};
var createDeterministicId = (namespace, ...parts) => {
  const fingerprint = hashDeterministicSeed([namespace, ...parts].join(":")).toString(36).padStart(7, "0");
  return `${namespace}_${fingerprint}`;
};

