  "services.role.rejection.reason.genreHelped": "Genre fit helped: Your {genre} reputation kept you in the conversation.",
  "services.role.rejection.reason.roomCraft": "Room read: The audition needed sharper craft and presence.",
  "services.role.rejection.reason.roomPackage": "Room read: The audition was competitive, but another package felt safer to the studio.",
  "services.role.rejection.reason.shortlist": "Shortlist pressure: The studio only called in a small group this week.",
  "services.role.rejection.reason.castingPressure": "Casting pressure: The room liked parts of your profile, but not enough to close the deal.",
  "services.role.rejection.reason.saferFit": "Casting wanted a safer fit for this project.",
  "services.role.rejection.hint.genre": "Build {genre} reputation with smaller work, then chase bigger roles in that lane.",
  "services.role.rejection.hint.fame": "Stack smaller roles, social reach, and press momentum to make bigger studios feel safer.",
  "services.role.rejection.hint.prep": "Keep audition prep high and stay active; close calls can turn into offers as your recent work improves.",
  "services.role.rejection.summary.application": "The team decided not to move forward before callbacks.",
  "services.role.rejection.summary.audition": "The room liked parts of your read, but the role went another way.",
  "services.role.rejection.review.intro.application": "Thanks for applying for {projectName}.",
  "services.role.rejection.review.intro.audition": "Thanks for coming in for {projectName}.",
  "services.role.rejection.review.directorNote": "Director note:\n{reason}",
