var clamp3 = (value, min, max) => Math.min(max, Math.max(min, value));
var getEstimatedBudget = (tier, rng = Math.random) => {
  const ranges = {
    LOW: [5e5, 12e6],
    MID: [12000001, 45e6],
    HIGH: [45000001, 12e7],
    BLOCKBUSTER: [120000001, 3e8]
  };
  const [min, max] = ranges[tier] || ranges.MID;
  const roll = rng();
  return Math.round(min + (max - min) * (Number.isFinite(roll) ? clamp3(roll, 0, 1) : 0.5));
};

