var MARKET_CAP_CEILING_BY_SECTOR = {
  TECH: 5e12,
  MEDIA: 75e10,
  FASHION: 65e10,
  BEVERAGE: 75e10,
  AUTOMOTIVE: 1e12
};
var REFERENCE_MARKET_CAP_BY_SECTOR = {
  TECH: 25e10,
  MEDIA: 4e10,
  FASHION: 5e10,
  BEVERAGE: 8e10,
  AUTOMOTIVE: 15e10
};
var MARKET_CAP_GROWTH_MULTIPLE_BY_SECTOR = {
  TECH: 2,
  MEDIA: 3,
  FASHION: 3,
  BEVERAGE: 3,
  AUTOMOTIVE: 3
};
var MIN_UNKNOWN_OUTSTANDING_SHARES = 25e7;
var MAX_UNKNOWN_OUTSTANDING_SHARES_RANGE = 175e7;
var stableShareHash = (value) => Array.from(value).reduce(
  (hash2, character) => hash2 * 31 + character.charCodeAt(0) >>> 0,
  2166136261
);
var roundPrice = (value) => Number(Math.max(0.01, value).toFixed(2));
var getGeneratedOutstandingShares = (stockId) => MIN_UNKNOWN_OUTSTANDING_SHARES + stableShareHash(stockId) % MAX_UNKNOWN_OUTSTANDING_SHARES_RANGE;
var getStockBaseOutstandingShares = (stock) => KNOWN_OUTSTANDING_SHARES[stock.id] || getGeneratedOutstandingShares(stock.id);
var getStockReferencePrice = (stock) => {
  const reference = KNOWN_REFERENCE_PRICES[stock.id];
  if (reference) return reference;
  const baseShares = getStockBaseOutstandingShares(stock);
  const referenceMarketCap = stock.sector ? REFERENCE_MARKET_CAP_BY_SECTOR[stock.sector] : 75e9;
  return roundPrice(Math.max(1, referenceMarketCap / baseShares));
};
var getStockMarketCapCeiling = (stock) => {
  const baseShares = getStockBaseOutstandingShares(stock);
  const referenceMarketCap = baseShares * getStockReferencePrice(stock);
  const sector = stock.sector;
  const growthMultiple = sector ? MARKET_CAP_GROWTH_MULTIPLE_BY_SECTOR[sector] : 3;
  const sectorCeiling = sector ? MARKET_CAP_CEILING_BY_SECTOR[sector] : 75e10;
  return Math.min(sectorCeiling, referenceMarketCap * growthMultiple);
};
