// services/boxOffice/boxOfficeMath.ts
var cinemaCount = (n, label) => {
  if (!Number.isSafeInteger(n) || n < 0) throw new RangeError(`Invalid cinema ${label}`);
  return n;
};
var cinemaKey = (seed2, week, key) => hashDeterministicSeed(`${seed2}:${week}:${key}`);
var apportionCinemaIntegers = (total, weights, seed2, week) => {
  cinemaCount(total, "apportion total");
  const denominator = weights.reduce((n, r) => n + BigInt(cinemaCount(r.weight, "weight")), 0n);
  const result = new Map(weights.map((r) => [r.id, 0]));
  if (!denominator) return result;
  const rows2 = weights.map((r) => {
    const numerator = BigInt(total) * BigInt(r.weight);
    return { ...r, base: Number(numerator / denominator), remainder: numerator % denominator };
  });
  for (const r of rows2) result.set(r.id, r.base);
  const left = total - rows2.reduce((n, r) => n + r.base, 0);
  rows2.sort((a, b) => a.remainder === b.remainder ? cinemaKey(seed2, week, a.id) - cinemaKey(seed2, week, b.id) || a.id.localeCompare(b.id) : a.remainder > b.remainder ? -1 : 1);
  for (const r of rows2.slice(0, left)) result.set(r.id, result.get(r.id) + 1);
  return result;
};

