// services/boxOffice/boxOfficeWeek.ts
var cinemaIndustryProjectDetails = (player, project) => {
  const production2 = Object.values(player.world.industryProductions || {}).find((p) => p.canonicalProjectId === project.id);
  const talent = production2?.studioAiExecution?.talent;
  const outside = player.outsideProductions?.find((p) => p.projectId === project.id);
  const quality = project.quality;
  const cast = (talent?.talentParticipation?.contracts || []).filter((c) => c.role === "ACTOR").map((c) => ({ id: c.talentId, actorId: c.talentId, name: c.talentName, role: "Cast", roleType: "SUPPORTING", type: "ACTOR", isPlayer: c.talentId === "PLAYER_SELF", image: "" }));
  if (project.leadActorId && !cast.some((c) => c.actorId === project.leadActorId))
    cast.push({ id: project.leadActorId, actorId: project.leadActorId, name: project.leadActorName, role: "Lead", roleType: "SUPPORTING", type: "ACTOR", isPlayer: project.leadActorId === "PLAYER_SELF", image: "" });
  const lead = cast.find((c) => c.actorId === project.leadActorId);
  if (lead)
    lead.roleType = "LEAD";
  return {
    title: project.title,
    type: "MOVIE",
    genre: project.genre,
    studioId: project.studioId,
    budgetTier: project.budgetTier,
    estimatedBudget: production2 ? production2.budgetMillions * 1e6 : outside?.budget || 0,
    description: outside?.logline || project.title,
    subtype: "STANDALONE",
    visibleHype: "LOW",
    visibleDirectorTier: "Established",
    visibleScriptBuzz: "Delivered",
    visibleCastStrength: "Delivered",
    releaseStrategy: project.releaseStrategy || "THEATRICAL",
    screeningStrategy: production2?.studioAiExecution?.selectedReleaseMode === "LIMITED_THEATRICAL" || outside?.releasePath === "FESTIVAL" ? "REGIONAL" : "INTERNATIONAL",
    directorId: project.directorId,
    directorName: project.directorName,
    castList: project.cinemaCast || cast,
    universeId: project.universeId,
    originalLanguageId: project.originalLanguageId || "english",
    releaseRegionIds: project.releaseRegionIds,
    cinemaExposure: project.cinemaExposure,
    talentParticipation: talent?.talentParticipation,
    hiddenStats: {
      qualityScore: quality,
      scriptQuality: production2?.writerSkill || outside?.scoutReport.scriptQuality || quality,
      directorQuality: outside?.scoutReport.directorQuality || quality,
      castingStrength: talent?.packageScore || outside?.scoutReport.castQuality || quality,
      rawHype: 0,
      distributionPower: 0,
      prestigeBonus: 0
    }
  };
};

// scripts/audit-studio-ai-commercial-result-b6.ts
var WEEK = 1600;
var studio = { id: "commercial", name: "Commercial House", valuation: 20, reputation: 78, cashReserve: 200, recentHits: 2, archetype: "COMMERCIAL" };
studio.ai = normalizeStudioAiState(studio, { absoluteWeek: WEEK });
var execution = { schemaVersion: 1, source: "STUDIO_INDEPENDENT", slateCommitmentId: "slate", fingerprintId: "fp", controllerAtLastProgression: "AI", selectedReleaseMode: "WIDE_THEATRICAL", publicReleaseStrategy: "THEATRICAL", releasePlannedAtAbsoluteWeek: WEEK - 2, plannedReleaseAbsoluteWeek: WEEK, releaseBlockedReason: "NONE", talentSelected: true, talent: { leadActorId: "a", leadActorName: "Actor", directorId: "d", directorName: "Director", packageScore: 82, estimatedCostMillions: 8 }, finalQuality: { creativeQuality: 82, executionQuality: 79, commercialPotential: 88, prestigePotential: 76, downsideRisk: 24 }, result: null, problems: [], paidMilestoneIds: ["PRE_PRODUCTION_START", "PRODUCTION_START", "POST_PRODUCTION_START", "DELIVERY"], processedKeys: [], lastProgressedAbsoluteWeek: WEEK - 1 };
var production = { id: "commercial_prod", canonicalProjectId: "commercial_project", title: "The Last Signal", projectType: "MOVIE", genre: "THRILLER", producerStudioId: studio.id, source: "STUDIO_INDEPENDENT", status: "AWAITING_RELEASE", productionCalendar: { preProductionWeeks: 4, productionWeeks: 8, postProductionWeeks: 4, totalWeeks: 16, weeksCompleted: 16, startedAge: 30, startedWeek: 20, startedAbsoluteWeek: WEEK - 18 }, budgetMillions: 60, paidMillions: 60, talentBookingIds: [], writerSource: "IN_HOUSE_TEAM", writerId: null, writerName: "Writers", writerSkill: 78, createdAtAbsoluteWeek: WEEK - 18, updatedAtAbsoluteWeek: WEEK - 1, studioAiSlateCommitmentId: "slate", industryContentFingerprintId: "fp", studioAiExecution: execution };
var world = { projects: [], studios: { [studio.id]: studio }, industryProductions: { [production.id]: production }, talentBookings: [] };
var first = releaseStudioAiProduction({ world, studio, production, absoluteWeek: WEEK });
assert.equal(first.changed, true);
assert.equal(first.production.status, "RELEASED");
assert.equal(first.world.projects.filter((row) => row.id === production.canonicalProjectId).length, 1);
assert.equal(first.project?.boxOffice, 0);
assert.equal(first.production.studioAiExecution?.result?.cinemaSettlement, "WEEKLY_PENDING");
assert.equal(first.production.studioAiExecution?.result?.studioReceiptsMillions, 0);
assert.equal(first.studio.cashReserve, studio.cashReserve - 60 * 0.18);
assert.equal(first.production.studioAiExecution?.result?.productionSpendMillions, 60);
assert.equal(first.studio.ai.ledger.filter((row) => ["RELEASE_MARKETING", "RIGHTS_INCOME"].includes(row.category)).length, 1);
var replay = releaseStudioAiProduction({ world: first.world, studio: first.studio, production: first.production, absoluteWeek: WEEK });
assert.equal(replay.changed, false);
assert.equal(replay.world.projects.filter((row) => row.id === production.canonicalProjectId).length, 1);
var streamingProduction = structuredClone(production);
streamingProduction.id = "stream_prod";
streamingProduction.canonicalProjectId = "stream_project";
streamingProduction.studioAiExecution.selectedReleaseMode = "STREAMING_ONLY";
streamingProduction.studioAiExecution.publicReleaseStrategy = "STREAMING_ONLY";
var streamWorld = { ...world, industryProductions: { [streamingProduction.id]: streamingProduction }, streamingRightsContracts: { right: { id: "right", sourceProjectId: streamingProduction.canonicalProjectId, buyerPlatformId: "NETFLIX", status: "ACTIVE", startsAtAbsoluteWeek: WEEK - 1, expiresAtAbsoluteWeek: WEEK + 50, exclusivity: "EXCLUSIVE", platformContentPlanId: null, countryIds: ["IN"], territory: "SELECTED_COUNTRIES" } } };
var streaming = releaseStudioAiProduction({ world: streamWorld, studio, production: streamingProduction, absoluteWeek: WEEK });
assert.equal(streaming.project?.boxOffice, 0);
assert.ok((streaming.project?.streamingWindows?.length || 0) > 0);
var regionalProduction = structuredClone(production);
regionalProduction.id = "regional-prod";
regionalProduction.canonicalProjectId = "regional-project";
regionalProduction.studioAiExecution.selectedReleaseMode = "LIMITED_THEATRICAL";
regionalProduction.studioAiExecution.fingerprintSnapshot = { originalLanguage: "HINDI", priorityMarket: "INDIA" };
var regional = releaseStudioAiProduction({ world, studio, production: regionalProduction, absoluteWeek: WEEK });
var campaign = regional.project.cinemaExposure.events.find((e) => e.kind === "PAID_CAMPAIGN");
assert.ok(campaign.countryIds?.includes("IN"), "A regional campaign reaches its selected market");
assert.ok(!campaign.countryIds?.includes("US"), "A regional campaign is not diluted across unreachable world markets");
assert.equal(regional.project.originalLanguageId, "hindi", "A new film retains its actual language");
var details = cinemaIndustryProjectDetails({ world: regional.world, outsideProductions: [] }, regional.project);
assert.equal(details.originalLanguageId, "hindi");
assert.deepEqual(details.releaseRegionIds, ["ASIA"]);
assert.equal(regional.studio.cashReserve, 200 - 60 * 0.08, "Campaign funding is still charged once");
var legacyRegional = structuredClone(regionalProduction);
delete legacyRegional.studioAiExecution.fingerprintSnapshot;
var knownStudio = structuredClone(studio);
knownStudio.ai.intelligence = { content: { selectedFingerprints: [{ id: "fp", originalLanguage: "HINDI", priorityMarket: "INDIA" }] } };
var legacyRelease = releaseStudioAiProduction({ world, studio: knownStudio, production: legacyRegional, absoluteWeek: WEEK });
assert.equal(legacyRelease.project.originalLanguageId, "hindi", "A missing snapshot retains still-known saved source language");
assert.deepEqual(legacyRelease.project.releaseRegionIds, ["ASIA"]);
var lostCampaignCash = releaseStudioAiProduction({ world, studio: { ...studio, cashReserve: 1 }, production, absoluteWeek: WEEK });
assert.equal(lostCampaignCash.production.status, "ON_HOLD", "A due release must re-check actual campaign cash");
assert.equal(lostCampaignCash.production.studioAiExecution.releaseBlockedReason, "INSUFFICIENT_MARKETING");
assert.equal(lostCampaignCash.studio.cashReserve, 1);
assert.equal(lostCampaignCash.project, null);
console.log("Studio AI B6 commercial result audit passed.");
